import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/%E8%8C%A8%E5%9F%8E%E8%A8%88%E7%94%BB.html","title":"茨城計画","lang":"en-US","frontmatter":{},"git":{"createdTime":1656750357000,"updatedTime":1759318871000,"contributors":[{"name":"Kazuma Arino","username":"","email":"hogeika2@gmail.com","commits":5}]},"readingTime":{"minutes":0.31,"words":94},"filePathRelative":"茨城計画.md"}`),a={name:`茨城計画.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="茨城計画" tabindex="-1"><a class="header-anchor" href="#茨城計画"><span>茨城計画</span></a></h1><p><a href="./ワーケーション.html">ワーケーション</a>というかサーフトリップ的に、常陸のあたりの友人宅にお邪魔しようプラン。</p><ul><li><a href="https://www.surf-life.blue/surf/spots/%E8%8C%A8%E5%9F%8E%E7%9C%8C/" target="_blank" rel="noopener noreferrer">茨城県のサーフポイント＆波情報｜Surf life</a></li><li><a href="http://nosurfing-nolife.com/spot/ibaraki.html" target="_blank" rel="noopener noreferrer">茨城のおススメのサーフィンスポット　-　サーフィンライフ</a></li><li><a href="https://www.manpuku.co.jp/bbq_ibaraki/spot/archives/1566" target="_blank" rel="noopener noreferrer">豊岡海岸(東海村)</a></li></ul><h2 id="簡単な記録" tabindex="-1"><a class="header-anchor" href="#簡単な記録"><span>簡単な記録</span></a></h2><p>2022/7/11から友人宅に合宿に来てみた。 海は波が良い時間はそこそこ混んでていまいちだったが、波がいまいちな時間は空いててしかもそれなりに乗れるので、 練習としては少し時間をずらして乗りまくるのが良いと思った。</p><p>友人宅に泊まるのは気を使うので、次はビジネスホテルとかにしたいが、 場所としては良い気がした。 友人宅のそばのビジネスホテルはそんなに高く無さそうなので、次はそこで試したい。</p>`,6)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};